package com.blackbox.app;

import java.io.FileNotFoundException;

import com.blackbox.graph.Canvas;
import com.blackbox.model.OnnxModel;

import javafx.application.Application;

public class App {
    public static void main(String[] args) {
        // Setup MVC
        Model model = new Model();
        Controller controller = new Controller(model);
        View.controller = controller;

        Connector connector = new Connector();
        System.out.println(connector.sayHello("arlo"));
        System.out.println(connector.trainSvc());
        OnnxModel onnx;
        try {
            onnx = new OnnxModel("SVM.onnx");
        } catch (FileNotFoundException e) {
            System.err.println(e);
            return;
        }
        onnx.getTrainingData();

        // Start JavaFX thread
        Thread javafxThread = new Thread(() -> {
            Application.launch(View.class, args);
            controller.stop();
        });
        javafxThread.start();

        // Run Canvas
        Canvas.run(controller.eventQueue);

        // Wait for JavaFX to exit
        try {
            javafxThread.join();
        } catch (InterruptedException e) {
            throw new RuntimeException("Canvas thread was interrupted");
        }
    }
}
